mapper.update:
UPDATE products
SET stock = stock - #{quantity}
WHERE id = #{productId}

mapper.select:
SELECT id, product_name AS productName, description, price, stock, image_url AS imageUrl, category_id AS categoryId, region_id AS regionId FROM products
AND product_name ILIKE '%' || #{keyword} || '%'
AND category_id = #{categoryId}
AND region_id = #{regionId}
AND price >= #{minPrice}
AND price <= #{maxPrice}
ORDER BY price ASC ORDER BY price DESC ORDER BY id ASC
